class Base64Images {
	//Store for base64 encoded headers, returns the encoded string based of the show acronym passed in
	constructor(show) {
		let exhib_cex =
			"data:image/jpeg;base64,";
		let exhib_spc =
			"data:image/jpeg;base64,";
		let exhib_bre =
			"data:image/jpeg;base64,";
		let exhib_fmx =
			"data:image/jpeg;base64,";
		let exhib_fme =
			"data:image/jpeg;base64,";
		let exhib_abx =
			"data:image/jpeg;base64,";
		
		switch (show) {
			case "SPC":
				this.image = exhib_spc;
				break;
			case "BRE":
				this.image = exhib_bre;
				break;
			case "FMX":
				this.image = exhib_fmx;
				break;
			case "FME":
				this.image = exhib_fme;
				break;
			case "ABX":
				this.image = exhib_abx;
				break;
			case "CEX":
				this.image = exhib_cex;
				break;
		}
	}
	getImage(){
		return this.image;
	}
}
export default Base64Images;
